{'id': 'inf-05-rate-limiting', 'description': 'Add rate limiting to API gateway: define limits, deploy, test, tune for optimal throughput', 'constraints': {'budget': {'max_tokens': None, 'max_calls': None, 'max_revisions': None}, 'time': None, 'environment': 'production', 'tools': ['terraform', 'aws-cli', 'curl', 'jmeter', 'python']}, 'risk_tolerance': 'balanced', 'replan_policy': 'patch', 'approval_ttl': None, 'metadata': {}}

